(7716689, 1268902, 30861, '<td valign="top">Like a Durer etching :-)</td>', 'Like a Durer etching :-)', '2022-03-14 16:15:31.000000', NULL, 1),
(7716690, 1268713, 30861, '<td valign="top">She''s quite serene here, but I glimpse steel underneath.</td>', 'She''s quite serene here, but I glimpse steel underneath.', '2022-03-14 16:16:30.000000', NULL, 1),
(7716691, 1268958, 30861, '<td valign="top">LOvely processing, but I find myself wanting faces (horse and/or rider) to make it more lively. Also, for me this is too much DOF, I am losing the subject in the BG...</td>', 'LOvely processing, but I find myself wanting faces (horse and/or rider) to make it more lively. Also, for me this is too much DOF, I am losing the subject in the BG...', '2022-03-14 16:24:42.000000', NULL, 1),
(7716692, 1268938, 30861, '<td valign="top">The tone are gorgeous, but the image reads as an exercise, there''s no sense of engagement here.</td>', 'The tone are gorgeous, but the image reads as an exercise, there''s no sense of engagement here.', '2022-03-14 16:25:25.000000', NULL, 1),
(7716693, 1268940, 30861, '<td valign="top">It''s a grand scene, but for me it''s composed and rendered in such a way as to minimize all that grandeur. The dark areas, especially, are just murky as heck :-(</td>', 'It''s a grand scene, but for me it''s composed and rendered in such a way as to minimize all that grandeur. The dark areas, especially, are just murky as heck :-(', '2022-03-14 16:26:48.000000', NULL, 1),
(7716694, 1268964, 30861, '<td valign="top">Eerily evocative. Makes me wonder where the feet are :-)</td>', 'Eerily evocative. Makes me wonder where the feet are :-)', '2022-03-14 16:27:40.000000', NULL, 1),
(7716695, 1268963, 30861, '<td valign="top">It''s like there''s nothing here, in a sense, to capture my attention and engage me. It''s an extremely static scene, the composition is lackluster, it''s just not very satisfying :-( I find myself wishing the mud, the wonderful muddy muddiness of the mud, played a bigger part here. THAT, I could get behind :-)</td>', 'It''s like there''s nothing here, in a sense, to capture my attention and engage me. It''s an extremely static scene, the composition is lackluster, it''s just not very satisfying :-( I find myself wishing the mud, the wonderful muddy muddiness of the mud, played a bigger part here. THAT, I could get behind :-)', '2022-03-14 16:31:21.000000', NULL, 1),
(7716696, 1268907, 30861, '<td valign="top">Remarkable rendering! Gloriously, intentionally overprocessed. I love it!</td>', 'Remarkable rendering! Gloriously, intentionally overprocessed. I love it!', '2022-03-14 16:32:49.000000', NULL, 1),
(7716697, 1268845, 30861, '<td valign="top">Beautifully rendered tone poem. Fabulous object, remarkable sky.</td>', 'Beautifully rendered tone poem. Fabulous object, remarkable sky.', '2022-03-14 16:33:29.000000', NULL, 1),
(7716698, 1268934, 30861, '<td valign="top">Nicely done, well-rendered, but in the end it leaves me wanting more. More what? I''m not sure, but it feels like some element of the concept is AWOL...</td>', 'Nicely done, well-rendered, but in the end it leaves me wanting more. More what? I''m not sure, but it feels like some element of the concept is AWOL...', '2022-03-14 16:34:40.000000', NULL, 1),
(7716699, 1268947, 30861, '<td valign="top">BEAUTIFUL control of the tones, classic Zone System stuff. Brave, centered composition. It works for me.</td>', 'BEAUTIFUL control of the tones, classic Zone System stuff. Brave, centered composition. It works for me.', '2022-03-14 16:35:32.000000', NULL, 1),
(7716700, 1268737, 30861, '<td valign="top">It''s not easy at ALL to capture the snow and the dark bison both, you''re showing considerable mastery of the medium :-) I''d like to see a tad more contrast, but it''s pretty close to optimal for my eye. The scene itself brings a smile. Well done!</td>', 'It''s not easy at ALL to capture the snow and the dark bison both, you''re showing considerable mastery of the medium :-) I''d like to see a tad more contrast, but it''s pretty close to optimal for my eye. The scene itself brings a smile. Well done!', '2022-03-14 16:38:24.000000', NULL, 1),
(7716701, 1268959, 30861, '<td valign="top">Hah! That''s an array, all right! Maybe a little muddier and low-key than it needs to be, but effective nevertheless.</td>', 'Hah! That''s an array, all right! Maybe a little muddier and low-key than it needs to be, but effective nevertheless.', '2022-03-14 16:39:52.000000', NULL, 1),
(7716702, 1268946, 30861, '<td valign="top">That''s pretty damned poignant :-( Well-seen!</td>', 'That''s pretty damned poignant :-( Well-seen!', '2022-03-14 16:41:35.000000', NULL, 1),
(7716703, 1268930, 30861, '<td valign="top">The processing here is a balancing job, just like the subject. Well done!</td>', 'The processing here is a balancing job, just like the subject. Well done!', '2022-03-14 16:42:21.000000', NULL, 1),
(7716704, 1268948, 30861, '<td valign="top">No kidding!</td>', 'No kidding!', '2022-03-14 16:42:38.000000', NULL, 1),
(7716705, 1268957, 30861, '<td valign="top">Just perfect! I''ve been doing shots like this through my windows in the last couple storms, but nothing came out this nice :-)</td>', 'Just perfect! I''ve been doing shots like this through my windows in the last couple storms, but nothing came out this nice :-)', '2022-03-14 16:44:38.000000', NULL, 1),
(7716714, 1268713, 75585, '<td valign="top">Gorgeous young model!  Not a fan of the crop.  What would have worked better (for me) is to crop horizontally with just about an inch below her chin (maybe 1.5) with her on the left half of the frame. . . But that is the beauty of art, so many different ways to present it.  I have this as a top finisher in my book!</td>', 'Gorgeous young model!  Not a fan of the crop.  What would have worked better (for me) is to crop horizontally with just about an inch below her chin (maybe 1.5) with her on the left half of the frame. . . But that is the beauty of art, so many different ways to present it.  I have this as a top finisher in my book!', '2022-03-14 18:09:25.000000', NULL, 1),
(7716715, 1268737, 75585, '<td valign="top">What a fun shot!  Hitchhikers!</td>', 'What a fun shot!  Hitchhikers!', '2022-03-14 18:10:19.000000', NULL, 1),
(7716716, 1268912, 75585, '<td valign="top">Great detail in this . . .good find and love the isolation.</td>', 'Great detail in this . . .good find and love the isolation.', '2022-03-14 18:13:09.000000', NULL, 1),
