(7716719, 1268886, 75585, '<td valign="top">Sign of an artist:  Taking the ordinary and making it extraordinary.</td>', 'Sign of an artist:  Taking the ordinary and making it extraordinary.', '2022-03-14 18:16:15.000000', NULL, 1),
