(7716722, 1268925, 75585, '<td valign="top">Love the light rays and you are absolutely right the light to dark in this is phenomenal!</td>', 'Love the light rays and you are absolutely right the light to dark in this is phenomenal!', '2022-03-14 18:32:27.000000', NULL, 1),
(7716723, 1268911, 75585, '<td valign="top">What a fun title - love the idea of sun sprites!  Had to do a double heck to see if that was a person or a shark in the waves LOL.</td>', 'What a fun title - love the idea of sun sprites!  Had to do a double heck to see if that was a person or a shark in the waves LOL.', '2022-03-14 18:33:43.000000', NULL, 1),
(7716724, 1268939, 75585, '<td valign="top">I can see this absolutely finishing in the top - the tones and detail in the feathers is great!  Wish the tip of the right wing wasnt cut off but that is nit picky . . It is great!  The foot falling off is my favorite part!</td>', 'I can see this absolutely finishing in the top - the tones and detail in the feathers is great!  Wish the tip of the right wing wasnt cut off but that is nit picky . . It is great!  The foot falling off is my favorite part!', '2022-03-14 18:35:23.000000', NULL, 1),
(7716725, 1268928, 75585, '<td valign="top">This is one of my favorites, great detail and interest through your composition.  Well done.</td>', 'This is one of my favorites, great detail and interest through your composition.  Well done.', '2022-03-14 18:38:13.000000', NULL, 1),
