(7717188, 1268934, 173844, '<td valign="top">Creative and charming, the magic touch.  The light is well utilized.  The people''s faces are captivating and well-wrought for the moment.  Just add snow.</td>', 'Creative and charming, the magic touch.  The light is well utilized.  The people''s faces are captivating and well-wrought for the moment.  Just add snow.', '2022-03-20 22:29:32.000000', NULL, 1),
(7717189, 1268819, 173844, '<td valign="top">An architect''s creation, but nicely seen and appreciated.  Wonderful choice for black and white, what with the spidery railings and the many adorning lines.  The contrasts against the white decor.  The lone person is a fine anchor.</td>', 'An architect''s creation, but nicely seen and appreciated.  Wonderful choice for black and white, what with the spidery railings and the many adorning lines.  The contrasts against the white decor.  The lone person is a fine anchor.', '2022-03-20 22:35:17.000000', NULL, 1),
(7717190, 1268926, 173844, '<td valign="top">Lovely portrait of this rabbit.  Uh, dog.  The harsh light is artfully handled.  The direct gaze draws you in, and enchants you.  A real character, I''ll bet.</td>', 'Lovely portrait of this rabbit.  Uh, dog.  The harsh light is artfully handled.  The direct gaze draws you in, and enchants you.  A real character, I''ll bet.', '2022-03-20 22:39:07.000000', NULL, 1),
(7717191, 1268737, 173844, '<td valign="top">A fine black and white as given by nature.  The magpies are flamboyant exclamation marks.  The stoic bison is forging his or her way through winter, amidst the snow and dried vegetation.  A winter''s tale.</td>', 'A fine black and white as given by nature.  The magpies are flamboyant exclamation marks.  The stoic bison is forging his or her way through winter, amidst the snow and dried vegetation.  A winter''s tale.', '2022-03-20 22:44:55.000000', NULL, 1),
